(function(root){
'use strict';const cache=new Map();
function mood(m){const gs=m.genres||[];if(gs.includes('Animation'))return{kind:'electric',rgb:[154,111,240],saturation:1.13};if(gs.includes('Mystery')||gs.includes('Crime'))return{kind:'noir',rgb:[171,183,190],saturation:.28};if(gs.includes('Horror'))return{kind:'shadow',rgb:[151,76,79],saturation:.65};if(gs.includes('Science Fiction'))return{kind:'cosmic',rgb:[101,153,184],saturation:.8};if(gs.includes('Adventure')||gs.includes('Fantasy'))return{kind:'epic',rgb:[190,148,89],saturation:.9};if(gs.includes('Romance'))return{kind:'warm',rgb:[196,137,140],saturation:.85};return{kind:'cinema',rgb:[137,163,161],saturation:.85}}
function palette(rgb){const c=rgb.map(v=>Math.max(0,Math.min(255,Number(v)||0)));return{accent:c.map(v=>Math.round(v*.6+255*.4)),surface:c.map(v=>Math.round(v*.055+4)),muted:c.map(v=>Math.round(v*.32+110))}}
function dominant(bytes){const bins=new Map();for(let i=0;i<bytes.length;i+=4){const rgb=[bytes[i],bytes[i+1],bytes[i+2]],hi=Math.max(...rgb),lo=Math.min(...rgb);if(hi<35||lo>230||hi-lo<18)continue;const key=rgb.map(v=>Math.floor(v/32)).join(',');let b=bins.get(key)||{sum:[0,0,0],weight:0,count:0};b.weight+=1+(hi-lo)/128;b.count++;rgb.forEach((v,j)=>b.sum[j]+=v);bins.set(key,b)}const best=[...bins.values()].sort((a,b)=>b.weight-a.weight)[0];return best?best.sum.map(v=>Math.round(v/best.count)):null}
function paint(el,m,rgb){const vibe=mood(m),p=palette(rgb||vibe.rgb);el.style.setProperty('--accent',p.accent.join(' '));el.style.setProperty('--surface',p.surface.join(' '));el.style.setProperty('--muted',p.muted.join(' '));el.style.setProperty('--art-saturation',vibe.saturation);el.dataset.mood=vibe.kind;}
function apply(el,m){el.dataset.themeTitle=m.id;const fallback=mood(m);paint(el,m,cache.get(m.id)||fallback.rgb);if(cache.has(m.id))return;const src=m.background||m.poster;if(!src?.startsWith('https://'))return;const img=new Image();img.crossOrigin='anonymous';img.onload=()=>{try{const canvas=document.createElement('canvas');canvas.width=canvas.height=48;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,48,48);let rgb=dominant(ctx.getImageData(0,0,48,48).data)||fallback.rgb;if(fallback.kind==='noir')rgb=fallback.rgb;cache.set(m.id,rgb);if(el.dataset.themeTitle===m.id)paint(el,m,rgb)}catch{cache.set(m.id,fallback.rgb)}};img.onerror=()=>cache.set(m.id,fallback.rgb);img.src=src;}
root.NoirThemes={apply,palette,dominant,mood};
})(typeof window==='undefined'?globalThis:window);
